// GLOBAL-PLACE-SEARCH-TEST-PAGE-A (2026-05-12): curated places dataset
// Loaded once at startup. Used by /api/search-place (the new isolated
// search engine that powers /search-test only — NOT the real homepage
// search box). Phase A scope: this dict is the ONLY source.
let _CURATED_PLACES = [];
// PLACE-SLUG-RESOLUTION-FIX-1 (2026-05-14): O(1) slug → entry index so any
// route / API / SSR resolver can fetch the full curated record without a
// linear scan of _CURATED_PLACES. Built once at startup right after the
// dataset loads; never mutated after that (load-once contract). Consumed
// by `_findPlaceBySlug` (the canonical slug-resolver used by SSR, the
// /api/place-by-slug endpoint, and any future resolvers).
let _CURATED_SLUG_INDEX = Object.create(null);
try {
    const _p = path.join(DB_DIR, 'places', 'curated-places.json');
    if (fs.existsSync(_p)) {
        const _raw = fs.readFileSync(_p, 'utf8');
        const _arr = JSON.parse(_raw);
        if (Array.isArray(_arr)) {
            _CURATED_PLACES = _arr.filter(_isPrayerTimesReady);
            for (const _p of _CURATED_PLACES) {
                if (_p && typeof _p.slug === 'string') {
                    // First occurrence wins (curated has no duplicate slugs
                    // by contract — _isPrayerTimesReady + per-wave dedupe
                    // guards enforce uniqueness — but be defensive).
                    if (!_CURATED_SLUG_INDEX[_p.slug]) _CURATED_SLUG_INDEX[_p.slug] = _p;
                }
            }
        }
    }
} catch (_) { /* silent — empty dataset = empty results, not a crash */ }

// Every prayer-times page needs lat + lng + timezone to compute. Drop
// any curated entry that's missing the contract — never surface a
// click target that can't render.
function _isPrayerTimesReady(p) {
    if (!p || typeof p !== 'object') return false;
    if (typeof p.slug !== 'string' || !/^[a-z0-9][a-z0-9-]{0,79}$/.test(p.slug)) return false;
    if (typeof p.countryCode !== 'string' || !/^[a-z]{2}$/.test(p.countryCode)) return false;
    const lat = Number(p.lat), lng = Number(p.lng);
    if (!isFinite(lat) || lat < -90 || lat > 90) return false;
    if (!isFinite(lng) || lng < -180 || lng > 180) return false;
    if (typeof p.timezone !== 'string' || !p.timezone) return false;
    if (!p.names || typeof p.names !== 'object') return false;
    return true;
}

// COUNTRY-PRAYER-PAGE-STRUCTURE-DATA-UX-ROOT-FIX-1 (2026-06-07): country city
// list sourced from the curated GLOBAL-PLACE-SEARCH dataset (names[lang] +
// canonical slug + lat/lng), replacing the legacy db/cities-*.json +
// STATIC_CITIES + Wikidata pipeline for /prayer-times-in-{country}. Returns the
// exact shape the prayer-times-cities.html renderer consumes. City NAMES follow
// the site rule names[lang] → names.en (NO runtime translation, NO fillchain);
// the card href uses the canonical curated slug so the city page always resolves.
function _curatedCitiesForCc(cc) {
    if (!cc || !/^[a-z]{2}$/.test(cc)) return [];
    const out = [];
    for (const p of _CURATED_PLACES) {
        if (p.countryCode !== cc) continue;
        const nm = p.names || {};
        out.push({
            slug: p.slug,
            lat: p.lat,
            lng: p.lng,
            names: nm,                          // full lang object → names[lang] → names.en
            nameAr: nm.ar || nm.en || p.slug,
            nameEn: nm.en || nm.ar || p.slug,
            priority: (typeof p.priority === 'number') ? p.priority : 0,
            _t: (p.type === 'city') ? 0 : 1   // city before town (temp sort key)
        });
    }
    // major-first: priority desc → city before town → alphabetical by English name (stable).
    out.sort((a, b) =>
        (b.priority - a.priority) ||
        (a._t - b._t) ||
        String(a.nameEn).localeCompare(String(b.nameEn))
    );
    for (const o of out) delete o._t;   // strip the temp sort key from the payload
    return out;
}

// MOON-COUNTRY-CAPITAL-MOON-LINKS-SECTION-1: resolve a country's CAPITAL to its CURATED entry (which
// carries a real slug), so the capital moon-links section is data-driven — never a hardcoded slug.
// Mirrors sortWithCapitalFirst's name match (English first-word OR exact Arabic name) + a lat/lng
// tiebreak to the capital's known coordinates (CAPITAL_DATA). Returns the curated city object
// ({slug, names, nameAr, nameEn, lat, lng}) or null when the capital is not a curated city (→ section skipped).
function _capitalCuratedEntry(cc) {
    try {
        const cap = (typeof CAPITAL_DATA !== 'undefined') ? CAPITAL_DATA[cc] : null;
        if (!cap) return null;
        const capEn0 = String(cap.nameEn || '').toLowerCase().split(' ')[0];
        const capAr = cap.nameAr || '';
        let best = null, bestD = Infinity;
        for (const c of _curatedCitiesForCc(cc)) {
            const enMatch = capEn0 && String(c.nameEn || '').toLowerCase().includes(capEn0);
            const arMatch = capAr && c.nameAr === capAr;
            if (!enMatch && !arMatch) continue;
            const d = Math.abs((c.lat || 0) - cap.lat) + Math.abs((c.lng || 0) - cap.lng);
            if (d < bestD) { bestD = d; best = c; }
        }
        return best;   // null when the capital is not among the curated cities
    } catch (_) { return null; }
}

// COUNTRY-PRAYER-PAGE-PREHYDRATED-CITIES-DATA-FIX-1: build a server-injected
// <script type="application/json" id="country-cities-data"> tag carrying the curated
// cities for `cc` (same shape + helper as /api/cities) so the client renders the country
// cities grid / city-page country section INSTANTLY with no /api/cities fetch and no spinner.
// `<` is <-escaped so a city name can never break out of the <script> element.
function _countryCitiesScriptTag(cc) {
    try {
        const list = _curatedCitiesForCc(cc);
        if (!list || !list.length) return '';
        return `<script type="application/json" id="country-cities-data">${JSON.stringify(list).replace(/</g, '\\u003c')}</script>`;
    } catch (_) { return ''; }
}

// MOON-COUNTRY-CITIES-BOX-CLS-FIX-1 (2026-06-25): SSR-render the FIRST PAGE (PER_PAGE=26, mirrors the
// template's renderGrid) of moon city cards for /moon/{country}, so #cities-container ships the REAL
// grid at first paint instead of the spinner. Previously the spinner (~1 row) was replaced client-side
// by the full 26-card grid (444px desktop / ~1955px mobile) → a large layout shift of everything below
// (section.mc-cities-box was Lighthouse's top CLS source, 0.163). Cards are shaped exactly like the
// client's renderGrid output (a.city-link → moon label + .city-type sub) PLUS a data-slug so the client
// re-wires the click-context without rebuilding the grid. Order/labels/hrefs mirror _curatedCitiesForCc
// (same sorted list the client gets) + the template's _cardLabelFn / _cityHref (moon variant).
const _MC_FIRST_PAGE = 26;   // === template PER_PAGE
function _moonCountryFirstPageGridHtml(cc, L) {
    try {
        const all = _curatedCitiesForCc(cc);
        if (!all || !all.length) return '';
        const cities = all.slice(0, _MC_FIRST_PAGE);
        const pfx = (L === 'ar') ? '' : '/' + L;
        const moonLabel = (cEn, cAr, cLoc) => {
            switch (L) {
                case 'en': return `Moon Today in ${cEn}`;
                case 'fr': return `Lune aujourd’hui à ${cLoc}`;
                case 'tr': return `${cLoc} bugün Ay`;
                case 'ur': return `${cLoc} میں آج چاند`;
                case 'de': return `Mond heute in ${cLoc}`;
                case 'id': return `Bulan Hari Ini di ${cLoc}`;
                case 'es': return `Luna hoy en ${cLoc}`;
                case 'bn': return `${cLoc}-এ আজ চাঁদ`;
                case 'ms': return `Bulan Hari Ini di ${cLoc}`;
                default:   return `قمر اليوم في ${cAr}`;
            }
        };
        const cards = cities.map(c => {
            const nm = c.names || {};
            const cEn = nm.en || c.nameEn || c.nameAr || '';
            const cAr = nm.ar || c.nameAr || cEn;
            const cLoc = nm[L] || nm.en || cEn;
            const sub = (L === 'ar') ? (nm.en || c.nameEn || '') : '';
            // MOON-COUNTRY-CITY-LINKS-NESTED-FRIENDLY-FIX-1 (2026-06-28): emit the NESTED direct
            // today URL /{lang}/moon/{country}/{city}/today instead of the legacy flat
            // /moon-today-in-{city} (which 301-redirects). _nestedMoonTodayLink resolves the country
            // from the slug (curated) + preserves the language prefix (pfx = '' for ar, '/xx' else),
            // with a graceful /moon fallback if unresolvable. No redirect hop → Friendly Links.
            const href = _nestedMoonTodayLink(c.slug, pfx);
            return `<a class="city-link" href="${_escHtml(href)}" data-slug="${_escHtml(c.slug)}">`
                + `${_escHtml(moonLabel(cEn, cAr, cLoc))}<span class="city-type">${_escHtml(sub)}</span></a>`;
        }).join('');
        return `<div class="cities-grid">${cards}</div>`;
    } catch (_) { return ''; }
}

// PRAYER-COUNTRY-SSR-GRID-AND-DATA-IN-BODY-FIX-1 (2026-07-03): the PRAYER twin of
