        'if(ar&&tr.getAttribute("data-ar")!=="1")ok=false;',
        'if(en&&tr.getAttribute("data-en")!=="1")ok=false;',
        'if(pick&&(parseInt(tr.getAttribute("data-pick"),10)||0)<pick)ok=false;',
        'if(q&&tr.getAttribute("data-text").indexOf(q)<0)ok=false;',
