// Preload + minify + compress async (terser is Promise-based)
// server.listen() awaits this via _preloadReady
const _cleanCss = new CleanCSS({ returnPromise: false, level: 2 });
async function _preloadStatic() {
    const _t0 = Date.now();
    let minSavings = 0;
    for (const rel of _preloadPaths) {
        try {
            const full = path.join(ROOT, rel);
            let data = fs.readFileSync(full);
            const originalSize = data.length;
            const ext = path.extname(rel).toLowerCase();
            try {
                if (ext === '.js') {
                    const src = data.toString('utf8');
                    const result = await Terser.minify(src, { compress: true, mangle: true });
                    if (result && result.code) data = Buffer.from(result.code, 'utf8');
                } else if (ext === '.css') {
                    const src = data.toString('utf8');
                    const result = _cleanCss.minify(src);
                    if (result && result.styles) {
                        data = Buffer.from(result.styles, 'utf8');
                        // حفظ النص لاستخدامه inline في HTML
                        if (rel === 'css/style.css') _inlineCssText = result.styles;
                        // Phase E5-a2: critical CSS (~15 KiB) inlined at top of <head>
                        if (rel === 'css/critical.css') _criticalCssText = result.styles;
                    }
                } else if (ext === '.html') {
                    // HIJRI-UMM-AL-QURA-STAGE-B1-ALGORITHM-FLIP (2026-05-23):
                    // Inject the lean Umm al-Qura table as window._HIJRI_UMM_AL_QURA
                    // just before js/hijri-date.js loads. This makes the table
                    // available synchronously to the deferred script. ~14 KB inline.
                    if (rel === 'index.html') {
                        const src = data.toString('utf8');
                        const marker = '<script defer src="js/hijri-date.js';
                        if (src.includes(marker) && !src.includes('window._HIJRI_UMM_AL_QURA')) {
                            const injected = src.replace(marker, _HIJRI_INLINE_SCRIPT + '\n    ' + marker);
                            data = Buffer.from(injected, 'utf8');
                        }
                    }
                    // IN-PAGE-SIDENAV-CONSISTENCY-ON-STATIC-AND-COUNTRY-PAGES-1 (2026-06-16):
                    // inject the single-source #sidebar into the <!--SHARED-SIDEBAR-->
                    // placeholder. index.html = SPA variant (no extra sprite; it already
                    // ships the full one); the 3 static templates = plain-href variant +
                    // a mini-sprite for the 11 sidebar icons.
                    if (_SIDENAV_TEMPLATES.has(rel)) {
                        const _src2 = data.toString('utf8');
                        if (_src2.includes('<!--SHARED-SIDEBAR-->')) {
                            const _isSpa = (rel === 'index.html');
                            const _bar = (_isSpa ? '' : _SIDENAV_SPRITE)
                                + _renderSidebar({ spa: _isSpa, active: _isSpa ? 'prayer-times' : null });
                            data = Buffer.from(_src2.replace('<!--SHARED-SIDEBAR-->', _bar), 'utf8');
                        }
                    }
                    // GA4-GOOGLE-TAG-PRODUCTION-INSTALL-1: bake the gtag.js snippet into
                    // the <head> of the 4 PUBLIC HTML templates (index.html / legal.html /
                    // countries.html / prayer-times-cities.html = _SIDENAV_TEMPLATES) — ONLY
                    // when GA is enabled by a valid GA_MEASUREMENT_ID env var. First-match
                    // replace hits the opening <head> tag (immediately, per Google's install
                    // guidance). No-op when GA is off → templates stay byte-identical.
                    if (_GA_ENABLED && _SIDENAV_TEMPLATES.has(rel)) {
                        const _src3 = data.toString('utf8');
                        if (_src3.includes('<head>')) {
                            data = Buffer.from(_src3.replace('<head>', '<head>' + _GA_HEAD_SNIPPET), 'utf8');
                        }
                    }
                }
            } catch (me) {
                console.warn(`[Minify] Skipped ${rel}: ${me.message}`);
            }
            minSavings += (originalSize - data.length);
            let gzipped = null, brotli = null;
            try { gzipped = zlib.gzipSync(data); } catch(e) {}
            try { brotli = zlib.brotliCompressSync(data, {
                params: { [zlib.constants.BROTLI_PARAM_QUALITY]: 11 } // أقصى ضغط — مرة واحدة عند الإقلاع فقط
            }); } catch(e) {}
            _staticCache.set(full, { data, gzipped, brotli });
        } catch(e) { /* الملف قد لا يكون موجوداً، تجاهل */ }
    }
    const _dt = Date.now() - _t0;
    console.log(`[Cache] Preloaded ${_staticCache.size} files in ${_dt}ms — minified (saved ${(minSavings/1024).toFixed(1)} KB) + gzip + brotli`);
}
const _preloadReady = _preloadStatic();

// مساعد يقرأ من الكاش أولاً، وإلا يعود للقرص
// يُستخدم لتقديم index.html و prayer-times-cities.html بسرعة من الذاكرة
function readCachedFile(fullPath, cb) {
    const cached = _staticCache.get(fullPath);
    if (cached) return setImmediate(() => cb(null, cached.data));
    fs.readFile(fullPath, cb);
}

