    'eid-al-fitr-countdown':    { occ: 'eid-fitr', ev: { m: 10, d: 1  }, pageId: 'page-eid-al-fitr-countdown',    h1Id: 'cd-h1-eid-fitr', faqId: 'fitr-faq-list', tbodyId: 'fitr-years-tbody', kp: 'eid_fitr' },
