            const _ctaC = _ctaCardI18n[Lm] || _ctaCardI18n.en;
            const _hubCtaHtml = `<a class="moon-hub-cta moon-hub-cta-pulse moon-hub-cta-card" href="${_escHtml(_hubCtaHref)}">`
